// Generates the catalog seed migration from the version-controlled definitions
// in src/lib so the database and the app never drift. Run: npm run db:seed-sql
import { writeFileSync } from "node:fs";
import { ASSIGNMENTS } from "../src/lib/assignments";
import { SCENARIOS } from "../src/lib/scenarios";

const q = (s: string) => `'${s.replace(/'/g, "''")}'`;
const arr = (xs: string[]) => `array[${xs.map(q).join(", ")}]::text[]`;

const lines: string[] = [
  "-- GENERATED by scripts/generate-seed.ts from src/lib — do not edit by hand.",
  "-- Catalog seed: missions and roleplay scenarios.",
  "",
];
for (const a of ASSIGNMENTS) {
  const rubric = JSON.stringify(a.criteria.map(({ key, label, competency, description }) => ({ key, label, competency, description })));
  lines.push(
    `insert into public.assignments (key, order_index, stage, title, description, competencies, rubric) values (${q(a.key)}, ${a.number}, ${q(a.stage)}, ${q(a.title)}, ${q(a.description)}, ${arr(a.competencies)}, ${q(rubric)}::jsonb)`,
    `  on conflict (key) do update set order_index = excluded.order_index, stage = excluded.stage, title = excluded.title, description = excluded.description, competencies = excluded.competencies, rubric = excluded.rubric;`,
  );
}
lines.push("");
for (const s of SCENARIOS) {
  lines.push(
    `insert into public.roleplay_scenarios (key, title, difficulty, objection, goal, focus_dimensions, is_active) values (${q(s.key)}, ${q(s.title)}, ${q(s.difficulty)}, ${q(s.objectionLabel)}, ${q(s.goal)}, ${arr(s.focusDimensions)}, true)`,
    `  on conflict (key) do update set title = excluded.title, difficulty = excluded.difficulty, objection = excluded.objection, goal = excluded.goal, focus_dimensions = excluded.focus_dimensions, is_active = true;`,
  );
}
writeFileSync("supabase/migrations/20261114000100_seed.sql", lines.join("\n") + "\n");
console.log(`Wrote ${ASSIGNMENTS.length} missions and ${SCENARIOS.length} scenarios.`);
